// Reads the AI Agent's reply (field "output") as JSON. Also accepts the old
// chat-completions shape, code fences, or extra text around the JSON.
function readAgentJson(r) {
  let c = r?.output ?? r?.choices?.[0]?.message?.content ?? r?.text;
  if (c && typeof c === 'object') return c;
  if (typeof c !== 'string') return {};
  c = c.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
  try { return JSON.parse(c); } catch (e) {}
  const a = c.indexOf('{');
  const b = c.lastIndexOf('}');
  if (a !== -1 && b > a) {
    try { return JSON.parse(c.slice(a, b + 1)); } catch (e) {}
  }
  return {};
}

const ESCALATIONS = [
  'escalate_no_valid_quotes',
  'escalate_no_on_time_quote',
  'escalate_no_faster_option',
  'escalate_no_alternative_supplier'
];

// Advisor responses come back in the same order as the items that escalated.
const planned = $('Select Best Safe Response').all()
  .map(i => i.json)
  .filter(j => ESCALATIONS.includes(j.status));

const responses = $input.all();

const clean = (v, max) =>
  String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);

const ALLOWED_OPTIONS = [
  'order_late',
  'split_shipment',
  'hold',
  'find_new_supplier'
];

return responses.map((item, index) => {
  const base = planned[index];

  if (!base) {
    return {
      json: {
        agent: 'response_planner',
        status: 'escalate_advisor_mismatch',
        auto_procurement_allowed: false,
        next_agent: 'orchestrator',
        errors: ['Matching escalation item is missing.']
      }
    };
  }

  const r = item.json ?? {};

  let t = {};

  t = readAgentJson(r);

  if (!t || typeof t !== 'object') t = {};

  const option = String(t.recommended_option ?? '').trim().toLowerCase();

  return {
    json: {
      ...base,

      // The advisor never changes a decision. Code set these; they stay.
      status: base.status,
      auto_procurement_allowed: false,
      next_agent: 'orchestrator',
      quote_id: base.quote_id,
      supplier_id: base.supplier_id,
      qty: base.qty,

      advisor_used: Boolean(t.recommendation),
      advisor_error: r.error
        ? JSON.stringify(r.error).slice(0, 300)
        : null,
      advisor_recommended_option: ALLOWED_OPTIONS.includes(option)
        ? option
        : null,
      advisor_recommendation:
        clean(t.recommendation, 700) ||
        `No safe automatic option. ${base.justification}`,
      advisor_tradeoffs: clean(t.tradeoffs, 700) || null,
      advisor_question_for_buyer: clean(t.question_for_buyer, 300) || null
    }
  };
});

const quoteItems = $input.all().map(i => i.json);
const candidates = $('Build Quote Candidates').all().map(i => i.json);

if (!candidates.length) {
  throw new Error('No quote candidates received from Build Quote Candidates.');
}

const DAY = 86400000;

// Unwrap common HTTP response formats.
function unwrap(raw) {
  let value = raw;

  for (let i = 0; i < 4; i++) {
    if (typeof value === 'string') {
      try {
        value = JSON.parse(value);
        continue;
      } catch {
        break;
      }
    }

    if (value?.body !== undefined && !value.quote_id) {
      value = value.body;
      continue;
    }

    if (value?.data !== undefined && !value.quote_id) {
      value = value.data;
      continue;
    }

    if (value?.result !== undefined && !value.quote_id) {
      value = value.result;
      continue;
    }

    break;
  }

  return value && typeof value === 'object'
    ? value
    : { error: 'Invalid quote response' };
}

function validDate(value) {
  const date = String(value ?? '').slice(0, 10);

  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return null;

  const ms = Date.parse(date + 'T00:00:00Z');

  if (!Number.isFinite(ms)) return null;

  return new Date(ms).toISOString().slice(0, 10) === date
    ? { date, ms }
    : null;
}

// The date the delayed stock actually lands if we order nothing.
// Agent 3 supplies delayed_pos[].new_eta. Earliest one is the soonest relief.
function waitingArrival(input) {
  const etas = (Array.isArray(input.delayed_pos) ? input.delayed_pos : [])
    .map(p => validDate(p.new_eta))
    .filter(Boolean)
    .map(d => d.ms);

  return etas.length ? Math.min(...etas) : null;
}

// Assess every response against its original request candidate.
const groups = new Map();

for (let i = 0; i < candidates.length; i++) {
  const candidate = candidates[i];
  const rawQuote = quoteItems[i] ?? {
    error: 'No quote response received'
  };

  const q = unwrap(rawQuote);

  const key = [
    candidate.scenario_id ?? '',
    candidate.incident_id ?? '',
    candidate.part_id
  ].join('|');

  if (!groups.has(key)) {
    groups.set(key, {
      input: candidate,
      assessed: [],
      errors: []
    });
  }

  const group = groups.get(key);

  const supplierId = String(q.supplier_id ?? candidate.supplier_id)
    .trim().toUpperCase();

  const partId = String(q.part_id ?? candidate.part_id)
    .trim().toUpperCase();

  const qty = Number(q.qty ?? candidate.qty);
  const mode = String(q.mode ?? candidate.mode).toLowerCase();
  const price = Number(q.total_aed);
  const arrival = validDate(q.earliest_arrival);

  const disruptedSupplier = String(
    candidate.disrupted_supplier_id ?? ''
  ).trim().toUpperCase();

  const matchesRequest =
    supplierId === String(candidate.supplier_id).toUpperCase() &&
    partId === String(candidate.part_id).toUpperCase() &&
    qty === Number(candidate.qty) &&
    mode === String(candidate.mode).toLowerCase();

  const supplierIsAlternative =
    !disruptedSupplier || supplierId !== disruptedSupplier;

  const valid = Boolean(
    q.quote_id &&
    matchesRequest &&
    supplierIsAlternative &&
    Number.isSafeInteger(qty) &&
    qty > 0 &&
    Number.isFinite(price) &&
    price > 0 &&
    arrival
  );

  if (!valid) {
    group.errors.push({
      supplier_id: candidate.supplier_id,
      mode: candidate.mode,
      error: q.error ?? q.detail ??
        (!matchesRequest
          ? 'Quote does not match requested candidate'
          : !supplierIsAlternative
            ? 'Disrupted supplier cannot be selected'
            : 'Invalid quote data')
    });
  }

  const required = validDate(candidate.required_by);

  group.assessed.push({
    quote_id: q.quote_id ?? null,
    supplier_id: supplierId,
    part_id: partId,
    qty,
    mode,
    total_aed: price,
    earliest_arrival: arrival?.date ?? null,
    arrival_ms: arrival?.ms ?? null,
    valid,
    arrives_on_time: Boolean(
      valid && required && arrival.ms <= required.ms
    ),
    days_late: valid && required
      ? Math.max(0, Math.ceil(
          (arrival.ms - required.ms) / DAY
        ))
      : null
  });
}

// Produce one procurement decision per affected part.
const results = [];

for (const group of groups.values()) {
  const input = group.input;

  const validQuotes = group.assessed.filter(q => q.valid);

  const requiredDate = validDate(input.required_by);
  const waitingMs = waitingArrival(input);

  const waitingDate = waitingMs !== null
    ? new Date(waitingMs).toISOString().slice(0, 10)
    : null;

  // Best case: lands by the production required date.
  const timely = validQuotes
    .filter(q => q.arrives_on_time)
    .sort((a, b) =>
      a.total_aed - b.total_aed ||
      a.arrival_ms - b.arrival_ms
    );

  // Late, but still sooner than the delayed shipment: reduces production loss.
  const improving = validQuotes
    .filter(q =>
      !q.arrives_on_time &&
      waitingMs !== null &&
      Number.isFinite(q.arrival_ms) &&
      q.arrival_ms < waitingMs
    )
    .sort((a, b) =>
      a.arrival_ms - b.arrival_ms ||
      a.total_aed - b.total_aed
    );

  // Everything else late, kept so escalations can name the earliest option.
  const late = validQuotes
    .filter(q => !q.arrives_on_time)
    .sort((a, b) =>
      a.arrival_ms - b.arrival_ms ||
      a.total_aed - b.total_aed
    );

  const selected = timely[0] ?? improving[0] ?? late[0] ?? null;

  const humanReviewRequired = input.requires_human_review === true;

  const beatsWaiting = Boolean(
    selected &&
    waitingMs !== null &&
    Number.isFinite(selected.arrival_ms) &&
    selected.arrival_ms < waitingMs
  );

  // Late orders are still allowed, but only when they help. If the best quote
  // lands no earlier than the delayed shipment itself, buying adds cost and
  // saves no time, so it goes to a human instead of Agent 5.
  // To go back to "order anything", set noBenefit to false.
  const noBenefit = Boolean(
    selected &&
    !selected.arrives_on_time &&
    waitingMs !== null &&
    !beatsWaiting
  );

  const ready = Boolean(selected && !humanReviewRequired && !noBenefit);

  const lateOrder = Boolean(ready && !selected.arrives_on_time);

  const daysSavedVsWaiting =
    selected && waitingMs !== null && Number.isFinite(selected.arrival_ms)
      ? Math.round((waitingMs - selected.arrival_ms) / DAY)
      : null;

  const productionLossDays =
    selected && requiredDate && Number.isFinite(selected.arrival_ms)
      ? Math.max(0, Math.ceil((selected.arrival_ms - requiredDate.ms) / DAY))
      : null;

  const status = !selected
    ? 'escalate_no_valid_quotes'
    : humanReviewRequired
      ? 'needs_human_review'
      : ready
        ? 'ready_for_procurement'
        : waitingMs === null
          ? 'escalate_no_on_time_quote'
          : 'escalate_no_faster_option';

  let justification;

  if (!selected) {
    justification =
      'No valid supplier quotations were returned. Human review is required.';
  } else if (humanReviewRequired) {
    justification =
      `Quote ${selected.quote_id} from ${selected.supplier_id} is available, ` +
      'but Agent 3 requires human review before procurement.';
  } else if (ready && selected.arrives_on_time) {
    justification =
      `Selected ${selected.supplier_id}, ${selected.mode} shipping, ` +
      `quote ${selected.quote_id}, costing AED ${selected.total_aed}. ` +
      `Arrival ${selected.earliest_arrival} meets required date ${input.required_by}.`;
  } else if (ready && beatsWaiting) {
    justification =
      `Selected ${selected.supplier_id}, ${selected.mode} shipping, ` +
      `quote ${selected.quote_id}, costing AED ${selected.total_aed}. ` +
      `Arrival ${selected.earliest_arrival} is after the required date ${input.required_by}, ` +
      `but ${daysSavedVsWaiting} day(s) earlier than the delayed shipment landing ${waitingDate}. ` +
      `Production loss is reduced to ${productionLossDays} day(s).`;
  } else if (ready) {
    justification =
      `Selected ${selected.supplier_id}, ${selected.mode} shipping, ` +
      `quote ${selected.quote_id}, costing AED ${selected.total_aed}. ` +
      `NOTE - DELAYED: arrival ${selected.earliest_arrival} is ` +
      `${productionLossDays} day(s) after the required date ${input.required_by}` +
      (waitingDate
        ? ` and not earlier than the delayed shipment landing ${waitingDate}. `
        : `; the delayed shipment has no known revised ETA. `) +
      `No quotation arrives on time, so the earliest available option is ordered.`;
  } else if (waitingMs === null) {
    justification =
      `No quotation meets required date ${input.required_by} and the delayed ` +
      `shipment has no known revised ETA, so the benefit of ordering cannot be ` +
      `established. Earliest option is ${selected.supplier_id}, ${selected.mode}, ` +
      `arriving ${selected.earliest_arrival}. Human escalation is required.`;
  } else {
    justification =
      `Ordering does not improve on waiting. The delayed shipment lands ` +
      `${waitingDate}; the earliest alternative is ${selected.supplier_id}, ` +
      `${selected.mode}, arriving ${selected.earliest_arrival}. Buying would add ` +
      `cost without reducing production loss. Human escalation is required.`;
  }

  // WHY THIS SUPPLIER: built from the quote data only, no AI text.
  // Agent 5 copies it into the PO justification word for word.
  let selectionReason = null;
  let selectionBasis = null;

  if (selected && (ready || humanReviewRequired)) {
    const disrupted = input.disrupted_supplier_id || 'The disrupted supplier';

    const whyNotDisrupted =
      `${disrupted} was not used: its shipment is delayed ${input.delay_days} day(s)` +
      (waitingDate ? ` and now lands ${waitingDate}` : '') +
      (waitingMs !== null && requiredDate && waitingMs > requiredDate.ms
        ? `, after the required date ${input.required_by}. `
        : '. ');

    const label =
      `${selected.supplier_id} ${selected.mode} (quote ${selected.quote_id}, ` +
      `AED ${selected.total_aed}, arrives ${selected.earliest_arrival})`;

    let whySelected;

    if (selected.arrives_on_time) {
      selectionBasis = 'lowest_cost_on_time';
      whySelected = timely.length > 1
        ? `${label} was chosen as the lowest-cost of ${timely.length} quotes arriving by the required date ${input.required_by}. `
        : `${label} was chosen as the only quote arriving by the required date ${input.required_by}. `;
    } else if (beatsWaiting) {
      selectionBasis = 'earliest_late_but_faster_than_waiting';
      whySelected =
        `No quote arrives by the required date ${input.required_by}. ` +
        `${label} was chosen as the earliest arrival, ${daysSavedVsWaiting} day(s) sooner than the delayed shipment. `;
    } else {
      selectionBasis = 'earliest_available';
      whySelected =
        `No quote arrives by the required date ${input.required_by}. ` +
        `${label} was chosen as the earliest available arrival. `;
    }

    const others = validQuotes
      .filter(q => q !== selected)
      .sort((a, b) => a.arrival_ms - b.arrival_ms || a.total_aed - b.total_aed);

    const whyNotOthers = others.length
      ? 'Other quotes compared: ' +
        others.slice(0, 3).map(q =>
          `${q.supplier_id} ${q.mode} AED ${q.total_aed} arriving ${q.earliest_arrival}` +
          (q.arrives_on_time ? '' : ` (${q.days_late} day(s) late)`)
        ).join('; ') +
        (others.length > 3 ? `; and ${others.length - 3} more.` : '.')
      : 'No other valid quote was returned.';

    selectionReason = whyNotDisrupted + whySelected + whyNotOthers;
  }

  const minOrderQty = Number(input.min_order_qty ?? 1);

  results.push({
    json: {
      ...input,

      agent: 'response_planner',
      status,
      auto_procurement_allowed: ready,
      next_agent: ready ? 'procurement' : 'orchestrator',

      selected_quote_id: selected?.quote_id ?? null,
      selected_supplier_id: selected?.supplier_id ?? null,
      selected_mode: selected?.mode ?? null,

      quote_id: selected?.quote_id ?? null,
      supplier_id: selected?.supplier_id ?? null,
      qty: selected?.qty ?? null,
      mode: selected?.mode ?? null,

      ordered_quantity: selected?.qty ?? null,
      minimum_order_quantity: minOrderQty,

      quantity_reason: selected
        ? selected.qty > Number(input.shortage_quantity)
          ? 'Minimum order quantity applied'
          : 'Actual shortage quantity'
        : null,

      estimated_total_aed: selected?.total_aed ?? null,
      quote_total_aed: selected?.total_aed ?? null,

      earliest_arrival: selected?.earliest_arrival ?? null,
      arrives_on_time: selected?.arrives_on_time ?? false,

      // CHANGE: late orders are allowed, but always labelled.
      late_order: lateOrder,
      delay_note: lateOrder
        ? `Delayed: arrives ${selected.earliest_arrival}, ` +
          `${productionLossDays} day(s) after required date ${input.required_by}.`
        : null,

      // Benefit of ordering, measured against doing nothing.
      disrupted_shipment_eta: waitingDate,
      beats_waiting: beatsWaiting,
      days_saved_vs_waiting: daysSavedVsWaiting,
      production_loss_days: productionLossDays,

      shortage_qty: input.shortage_quantity,
      need_date: input.required_by,

      justification,
      reasoning_summary: justification,

      // Why the selected supplier was used instead of the disrupted one.
      selection_reason: selectionReason,
      selection_basis: selectionBasis,

      quote_errors: group.errors,

      comparison: validQuotes
        .sort((a, b) =>
          Number(b.arrives_on_time) - Number(a.arrives_on_time) ||
          a.days_late - b.days_late ||
          a.total_aed - b.total_aed
        )
        .map(q => ({
          quote_id: q.quote_id,
          supplier_id: q.supplier_id,
          part_id: q.part_id,
          qty: q.qty,
          mode: q.mode,
          total_aed: q.total_aed,
          earliest_arrival: q.earliest_arrival,
          arrives_on_time: q.arrives_on_time,
          days_late: q.days_late,
          beats_waiting: waitingMs !== null &&
            Number.isFinite(q.arrival_ms) &&
            q.arrival_ms < waitingMs
        }))
    }
  });
}

// Parts with no alternative supplier never got a quote request.
// Report them as escalations instead of silently dropping them.
for (const h of $('Validate Input').all().map(i => i.json)) {
  const key = [h.scenario_id ?? '', h.incident_id ?? '', h.part_id].join('|');

  if (groups.has(key)) continue;

  const reason =
    `No qualified alternative supplier is available for ${h.part_id} ` +
    `(disrupted supplier ${h.supplier_id}). Human escalation is required.`;

  results.push({
    json: {
      ...h,
      agent: 'response_planner',
      status: 'escalate_no_alternative_supplier',
      auto_procurement_allowed: false,
      next_agent: 'orchestrator',
      disrupted_supplier_id: h.supplier_id,
      selected_quote_id: null,
      selected_supplier_id: null,
      selected_mode: null,
      quote_id: null,
      supplier_id: null,
      qty: null,
      mode: null,
      estimated_total_aed: null,
      quote_total_aed: null,
      earliest_arrival: null,
      arrives_on_time: false,
      disrupted_shipment_eta: null,
      beats_waiting: false,
      days_saved_vs_waiting: null,
      production_loss_days: null,
      shortage_qty: h.shortage_quantity,
      need_date: h.required_by,
      justification: reason,
      reasoning_summary: reason,
      selection_reason: null,
      selection_basis: null,
      quote_errors: [],
      comparison: []
    }
  });
}

return results;

const inventoryItems = $input.all().map(i => i.json);
const handoffs = $('Validate Input').all().map(i => i.json);

if (!inventoryItems.length || inventoryItems.length !== handoffs.length) {
  throw new Error('Inventory results and validated handoffs do not match.');
}

const candidates = [];
const noAlternative = [];

function parseResponse(value) {
  if (typeof value === 'string') {
    return JSON.parse(value);
  }
  return value;
}

function supplierList(value) {
  if (Array.isArray(value)) return value;
  if (typeof value === 'string') return value.split(',');
  return [];
}

for (let i = 0; i < inventoryItems.length; i++) {
  let inventory = inventoryItems[i];

  if (inventory.body !== undefined) {
    inventory = parseResponse(inventory.body);
  }

  if (inventory.data && !inventory.part) {
    inventory = inventory.data;
  }

  const part = inventory.part ?? inventory;
  const input = handoffs[i];

  if (!part?.part_id) {
    throw new Error(`Part information missing for ${input.part_id}`);
  }

  if (String(part.part_id).toUpperCase() !== input.part_id) {
    throw new Error(`Inventory part does not match handoff part ${input.part_id}`);
  }

  const shortageQty = Number(input.shortage_quantity);
  const minOrderQty = Number(part.min_order_qty ?? 1);

  if (!Number.isSafeInteger(shortageQty) || shortageQty <= 0) {
    throw new Error(`Invalid shortage quantity for ${input.part_id}`);
  }

  if (!Number.isSafeInteger(minOrderQty) || minOrderQty <= 0) {
    throw new Error(`Invalid minimum order quantity for ${input.part_id}`);
  }

  const disruptedSupplier = String(input.supplier_id ?? '')
    .trim()
    .toUpperCase();

  const suppliers = [
    ...supplierList(part.preferred_supplier),
    ...supplierList(part.qualified_alternates)
  ]
    .map(s => String(s).trim().toUpperCase())
    .filter(s => /^S\d{2}$/.test(s));

  const uniqueSuppliers = [...new Set(suppliers)]
    .filter(s => s !== disruptedSupplier);

  if (!uniqueSuppliers.length) {
    // FIX: do not stop the whole run for one part. Skip it here;
    // 'Select Best Safe Response' reports it as an escalation.
    noAlternative.push(
      `${input.part_id} (disrupted supplier ${disruptedSupplier || 'unknown'})`
    );
    continue;
  }

  const orderQty = Math.max(shortageQty, minOrderQty);

  for (const supplierId of uniqueSuppliers) {
    for (const mode of ['sea', 'air']) {
      candidates.push({
        json: {
          ...input,
          disrupted_supplier_id: disruptedSupplier || null,
          supplier_id: supplierId,
          part_id: input.part_id,
          qty: orderQty,
          mode,
          shortage_quantity: shortageQty,
          min_order_qty: minOrderQty,
          quantity_reason: orderQty > shortageQty
            ? 'Minimum order quantity applied'
            : 'Actual shortage quantity'
        }
      });
    }
  }
}

// Nothing at all can be quoted: fail with a clear message.
// The orchestrator catches this and Agent 5 reports it for human review.
if (!candidates.length) {
  throw new Error(
    'No qualified alternative supplier available for: ' + noAlternative.join(', ')
  );
}

return candidates;

const items = $input.all().map(item => item.json);
const results = [];

const getText = (...values) => {
  const value = values.find(v =>
    v !== undefined && v !== null && String(v).trim() !== ''
  );
  return value === undefined ? '' : String(value).trim();
};

for (const raw of items) {
  // Skip blank passthrough items from IF / Filter / NoOp nodes.
  if (!raw || Object.keys(raw).length === 0) {
    continue;
  }

  const status = getText(raw.status);

  // Valid outcomes that do not require procurement.
  if (
    status === 'no_action_needed' ||
    status === 'needs_human_review'
  ) {
    continue;
  }

  if (status !== 'shortage_handoff_to_agent4') {
    throw new Error(
      `Unexpected Agent 3 handoff status: ${status || 'missing'}. ` +
      `Item keys: ${Object.keys(raw).join(', ') || 'none'}`
    );
  }

  const scenarioId = getText(raw.scenario_id);
  const incidentId = getText(raw.incident_id);
  const supplierId = getText(raw.supplier_id).toUpperCase();
  const partId = getText(raw.part_id).toUpperCase();

  const qty = Number(raw.shortage_quantity);
  const delayDays = Number(raw.delay_days);

  // Accept supported date field names.
  const requiredByRaw = getText(
    raw.required_by,
    raw.need_date,
    raw.required_by_date,
    raw.required_date,
    raw.need_by_date,
    raw.production_required_by
  );

  const requiredBy = requiredByRaw.slice(0, 10);

  const productionAtRisk = raw.production_at_risk === true;

  const riskLevel = getText(raw.risk_level, 'UNKNOWN')
    .toUpperCase();

  const affectedOrders = Array.isArray(raw.affected_orders)
    ? raw.affected_orders.map(String)
    : [];

  const sourceIds = Array.isArray(raw.source_ids)
    ? raw.source_ids.map(String)
    : [];

  if (!/^P\d{3}$/.test(partId)) {
    throw new Error(`Invalid part_id: ${partId}`);
  }

  if (!/^S\d{2}$/.test(supplierId)) {
    throw new Error(`Invalid supplier_id: ${supplierId}`);
  }

  if (!Number.isSafeInteger(qty) || qty <= 0) {
    throw new Error(`Invalid shortage_quantity for ${partId}`);
  }

  if (
    !Number.isFinite(delayDays) ||
    delayDays <= 0 ||
    delayDays > 365
  ) {
    throw new Error(`Invalid delay_days for ${partId}`);
  }

  if (!productionAtRisk) {
    throw new Error(
      `${partId} was not marked as production_at_risk`
    );
  }

  // Validate the required production date.
  const date = new Date(`${requiredBy}T00:00:00.000Z`);

  if (
    !/^\d{4}-\d{2}-\d{2}$/.test(requiredBy) ||
    Number.isNaN(date.getTime()) ||
    date.toISOString().slice(0, 10) !== requiredBy
  ) {
    throw new Error(
      `Missing or invalid required date for ${partId}. ` +
      `Agent 3 must supply required_by or need_date. ` +
      `Received date value: ${requiredByRaw || 'none'}.`
    );
  }

  results.push({
    json: {
      ...raw,
      scenario_id: scenarioId || null,
      incident_id: incidentId || null,
      supplier_id: supplierId,
      part_id: partId,
      shortage_quantity: qty,
      delay_days: delayDays,
      required_by: requiredBy,
      production_at_risk: true,
      risk_level: riskLevel,
      affected_orders: affectedOrders,
      source_ids: sourceIds
    }
  });
}

return results;
